// Structure n8n : inputData.json.body contient nos données
const webhookData = $input.item.json.body;

console.log('🔍 DEBUG final:');
console.log('Données webhook:', JSON.stringify(webhookData, null, 2));
console.log('Type:', typeof webhookData);
console.log('Clés:', webhookData ? Object.keys(webhookData) : 'null/undefined');

// Configuration Flask
const flaskConfig = {
  ip: '192.168.1.15',
  port: 5003,
  url: 'http://192.168.1.15:5003'
};

// Validation
if (!webhookData || typeof webhookData !== 'object') {
  throw new Error('webhookData invalide: ' + JSON.stringify(webhookData));
}

if (!webhookData.contenu) {
  throw new Error('Champ "contenu" manquant. Clés disponibles: ' + Object.keys(webhookData).join(', '));
}

if (!webhookData.image_urls) {
  throw new Error('Champ "image_urls" manquant. Clés disponibles: ' + Object.keys(webhookData).join(', '));
}

// Traiter les URLs d'images
let imageUrls = [];
if (typeof webhookData.image_urls === 'string') {
  imageUrls = webhookData.image_urls.split(',').map(url => url.trim()).filter(url => url);
} else if (Array.isArray(webhookData.image_urls)) {
  imageUrls = webhookData.image_urls.filter(url => url && url.trim());
}

console.log('✅ SUCCESS!');
console.log('Contenu:', webhookData.contenu.substring(0, 50) + '...');
console.log('Images:', imageUrls.length, imageUrls);

return {
  json: {
    contenu: webhookData.contenu,
    image_urls: imageUrls,
    flask_config: flaskConfig,
    dynamic_urls: {
      create_layout: flaskConfig.url + '/api/create-layout-urls',
      download_base: flaskConfig.url + '/api/download/'
    }
  }
};

// Debug complet pour comprendre la réponse OpenAI
const aiData = $input.item;
const webhookData = $node["🌐 Détecteur Simple"].json;

console.log('🤖 DEBUG IA - Structure complète:', JSON.stringify(aiData, null, 2));
console.log('🔧 Données webhook:', webhookData ? Object.keys(webhookData) : 'null');

// Essayer différentes sources pour la réponse IA
let aiResponse = null;
let source = 'non trouvée';

if (aiData.json) {
  console.log('📋 Clés dans aiData.json:', Object.keys(aiData.json));

  if (aiData.json.text) {
    aiResponse = aiData.json.text;
    source = 'json.text';
  } else if (aiData.json.output) {
    aiResponse = aiData.json.output;
    source = 'json.output';
  } else if (aiData.json.response) {
    aiResponse = aiData.json.response;
    source = 'json.response';
  } else if (aiData.json.message) {
    aiResponse = aiData.json.message;
    source = 'json.message';
  } else if (aiData.json.content) {
    aiResponse = aiData.json.content;
    source = 'json.content';
  }
} else {
  console.log('📋 Clés dans aiData:', Object.keys(aiData));
}

if (!aiResponse) {
  // Essayer les propriétés directes
  if (aiData.text) {
    aiResponse = aiData.text;
    source = 'text';
  } else if (aiData.output) {
    aiResponse = aiData.output;
    source = 'output';
  } else if (aiData.response) {
    aiResponse = aiData.response;
    source = 'response';
  }
}

console.log('🤖 Réponse IA source:', source);
console.log('🤖 Type de aiResponse:', typeof aiResponse);
console.log('🤖 Réponse IA trouvée:', aiResponse ? (typeof aiResponse === 'string' ? aiResponse.substring(0, 200) + '...' : JSON.stringify(aiResponse)) : 'AUCUNE');

// Validation
if (!webhookData) {
  throw new Error('Aucune donnée du nœud Détecteur Simple');
}

// Continuer même sans réponse IA pour débugger
if (!aiResponse) {
  console.log('⚠️ Pas de réponse IA, utilisation de valeurs par défaut');
  aiResponse = '{"title": "Titre par défaut", "subtitle": "Sous-titre par défaut", "body": "Corps par défaut"}';
}

// Parser la réponse JSON d'OpenAI
let analysis;
try {
  const cleanResponse = aiResponse.replace(/```json\n?|```\n?/g, '').trim();
  analysis = JSON.parse(cleanResponse);
  console.log('✅ Analyse IA parsée:', analysis);
} catch (e) {
  console.log('❌ Erreur parsing IA:', e.message);
  analysis = {
    title: 'Titre générique',
    subtitle: 'Sous-titre générique',
    body: webhookData.contenu || 'Contenu générique'
  };
}

// Compter les images
const imageCount = webhookData.image_urls ? webhookData.image_urls.length : 0;
const imageUrls = webhookData.image_urls || [];

// Sélectionner le template selon le nombre d'images
let template;
if (imageCount === 1) {
  template = 'template-mag-simple-1808';
} else if (imageCount >= 2) {
  template = 'template-mag-simple-2-1808';
} else {
  template = 'template-mag-simple-1808';
}

console.log('📋 Template sélectionné: ' + template + ' (' + imageCount + ' images)');

return {
  json: {
    ai_analysis: {
      title: analysis.title,
      subtitle: analysis.subtitle,
      body: analysis.body
    },
    template_selection: {
      template: template,
      image_count: imageCount,
      reason: imageCount + ' image(s) détectée(s)'
    },
    image_data: {
      urls: imageUrls,
      count: imageCount
    },
    flask_config: webhookData.flask_config,
    dynamic_urls: webhookData.dynamic_urls,
    original_content: webhookData.contenu,
    debug: {
      ai_raw_response: aiResponse,
      ai_source: source,
      ai_data_keys: aiData.json ? Object.keys(aiData.json) : Object.keys(aiData),
      webhook_keys: webhookData ? Object.keys(webhookData) : []
    }
  }
};

