const response = $input.item.json;
const processedData = $node["📋 Traitement Final"].json;

console.log('📊 Réponse Flask:', response);
console.log('🎯 Configuration utilisée:', processedData.flask_config);

if (response.success) {
  return {
    json: {
      status: 'success',
      message: '🎉 Document InDesign créé avec succès !',
      details: {
        flask_config: processedData.flask_config,
        template_used: processedData.template_selection.template,
        image_count: processedData.template_selection.image_count,
        ai_analysis: {
          title: processedData.ai_analysis.title,
          subtitle: processedData.ai_analysis.subtitle,
          body_preview: processedData.ai_analysis.body.substring(0, 100) + '...'
        },
        debug: {
          used_url: processedData.dynamic_urls.create_layout,
          ai_raw: processedData.debug.ai_raw_response,
          ai_source: processedData.debug.ai_source
        }
      },
      project_id: response.project_id,
      download_url: processedData.dynamic_urls.download_base + response.project_id
    }
  };
} else {
  return {
    json: {
      status: 'error',
      message: '❌ Erreur: ' + (response.error || 'Erreur inconnue'),
      debug: {
        flask_response: response,
        flask_config: processedData.flask_config,
        used_url: processedData.dynamic_urls.create_layout,
        ai_debug: processedData.debug
      }
    }
  };
}
